const input = $input.first()?.json || {};
const notionRecords = input.notionRecords || [];
const linearRecords = input.linearRecords || [];
const stateRecords = input.stateRecords || [];
const conflictStrategy = input.conflictStrategy || 'last-write-wins';

const linearById = new Map(linearRecords.filter((record) => record.linearId).map((record) => [record.linearId, record]));
const stateByPair = new Map(stateRecords.map((record) => [`${record.notionId || ''}::${record.linearId || ''}`, record]));
const touchedLinearIds = new Set();

function asMillis(value) {
  if (!value) return 0;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? 0 : date.getTime();
}

function resolveConflict(notionChanged, linearChanged, notionRecord, linearRecord) {
  if (notionChanged && !linearChanged) return 'notion';
  if (linearChanged && !notionChanged) return 'linear';
  if (!notionChanged && !linearChanged) return 'none';
  if (conflictStrategy === 'notion-primary') return 'notion';
  if (conflictStrategy === 'linear-primary') return 'linear';
  return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear';
}

const changes = [];

for (const notionRecord of notionRecords) {
  const linearRecord = notionRecord.linearId ? linearById.get(notionRecord.linearId) : undefined;
  const state = stateByPair.get(`${notionRecord.notionId || ''}::${notionRecord.linearId || linearRecord?.linearId || ''}`) || null;

  if (!linearRecord) {
    changes.push({ action: 'create', source: 'notion', target: 'linear', entityType: input.entityType, record: notionRecord, state });
    continue;
  }

  touchedLinearIds.add(linearRecord.linearId);

  const notionChanged = !state || asMillis(notionRecord.updatedAt) > asMillis(state.notionLastModified);
  const linearChanged = !state || asMillis(linearRecord.updatedAt) > asMillis(state.linearLastModified);
  const contentChanged = notionRecord.contentHash !== linearRecord.contentHash;

  if (!contentChanged) continue;

  const winner = resolveConflict(notionChanged, linearChanged, notionRecord, linearRecord);
  if (winner === 'notion') {
    changes.push({ action: 'update', source: 'notion', target: 'linear', entityType: input.entityType, record: notionRecord, counterpart: linearRecord, state });
  } else if (winner === 'linear') {
    changes.push({ action: 'update', source: 'linear', target: 'notion', entityType: input.entityType, record: linearRecord, counterpart: notionRecord, state });
  }
}

for (const linearRecord of linearRecords) {
  if (touchedLinearIds.has(linearRecord.linearId)) continue;
  const state = stateRecords.find((record) => record.linearId === linearRecord.linearId) || null;
  changes.push({ action: 'create', source: 'linear', target: 'notion', entityType: input.entityType, record: linearRecord, state });
}

return [{
  json: {
    entityType: input.entityType,
    conflictStrategy,
    changes,
    counts: {
      total: changes.length,
      notionToLinear: changes.filter((change) => change.target === 'linear').length,
      linearToNotion: changes.filter((change) => change.target === 'notion').length
    }
  }
}];
